// A standalone JSON assignment converter, implemented from its documented
// interface and black-box observations. It has no third-party dependencies.
package main

import (
    "bufio"
    "crypto/tls"
    "errors"
    "flag"
    "fmt"
    "io"
    "net/http"
    "net/url"
    "os"
    "strings"
    "syscall"
    "unsafe"
)

const helpText = `Transform JSON (from a file, URL, or stdin) into discrete assignments to make it greppable

Usage:
  gron [OPTIONS] [FILE|URL|-]

Options:
  -u, --ungron     Reverse the operation (turn assignments back into JSON)
  -v, --values     Print just the values of provided assignments
  -c, --colorize   Colorize output (default on tty)
  -m, --monochrome Monochrome (don't colorize output)
  -s, --stream     Treat each line of input as a separate JSON object
  -k, --insecure   Disable certificate validation
  -x, --proxy      Set proxy configuration
      --noproxy    Comma-separated list of hosts for which not to use a proxy, if one is specified.
  -j, --json       Represent gron data as JSON stream
      --no-sort    Don't sort output (faster)
      --version    Print version information

Exit Codes:
  0	OK
  1	Failed to open file
  2	Failed to read input
  3	Failed to form statements
  4	Failed to fetch URL
  5	Failed to parse statements
  6	Failed to encode JSON

Examples:
  gron /tmp/apiresponse.json
  gron http://jsonplaceholder.typicode.com/users/1 
  curl -s http://jsonplaceholder.typicode.com/users/1 | gron
  gron http://jsonplaceholder.typicode.com/users/1 | grep company | gron --ungron
`

type options struct {
    reverse, values, color, mono, stream, insecure, json, noSort, version bool
    proxy, noProxy string
    useColor, ansi bool
}

func terminal(f *os.File) bool {
    var term syscall.Termios
    _, _, err := syscall.Syscall6(syscall.SYS_IOCTL, f.Fd(), syscall.TCGETS, uintptr(unsafe.Pointer(&term)), 0, 0, 0)
    return err == 0
}

func main() { os.Exit(run(os.Args[1:])) }

func run(args []string) int {
    var opt options
    fs := flag.NewFlagSet("gron", flag.ContinueOnError)
    fs.SetOutput(os.Stderr)
    fs.Usage = func() { fmt.Fprint(os.Stderr, helpText) }
    boolFlags := []struct { short, long string; value *bool } {
        {"u", "ungron", &opt.reverse}, {"v", "values", &opt.values},
        {"c", "colorize", &opt.color}, {"m", "monochrome", &opt.mono},
        {"s", "stream", &opt.stream}, {"k", "insecure", &opt.insecure},
        {"j", "json", &opt.json},
    }
    for _, f := range boolFlags {
        fs.BoolVar(f.value, f.short, false, "")
        fs.BoolVar(f.value, f.long, false, "")
    }
    fs.BoolVar(&opt.noSort, "no-sort", false, "")
    fs.BoolVar(&opt.version, "version", false, "")
    fs.StringVar(&opt.proxy, "x", "", "")
    fs.StringVar(&opt.proxy, "proxy", "", "")
    fs.StringVar(&opt.noProxy, "noproxy", "", "")
    if err := fs.Parse(args); err != nil {
        if errors.Is(err, flag.ErrHelp) { return 0 }
        return 2
    }
    if opt.version {
        fmt.Fprintln(os.Stdout, "gron version dev")
        return 0
    }
    opt.useColor = opt.color || (!opt.mono && terminal(os.Stdout) && os.Getenv("TERM") != "dumb")
    opt.ansi = opt.useColor && os.Getenv("NO_COLOR") == ""
    var input io.ReadCloser = os.Stdin
    name := fs.Arg(0)
    if name != "" && name != "-" {
        var err error
        low := strings.ToLower(name)
        if strings.HasPrefix(low, "http://") || strings.HasPrefix(low, "https://") {
            input, err = fetch(name, opt)
            if err != nil { fmt.Fprintln(os.Stderr, err); return 4 }
        } else {
            input, err = os.Open(name)
            if err != nil { fmt.Fprintln(os.Stderr, err); return 1 }
        }
    }
    defer input.Close()
    if opt.reverse { return reverse(input, os.Stdout, opt) }
    if opt.values { return values(input, os.Stdout) }
    return forward(input, os.Stdout, opt)
}

func fetch(address string, opt options) (io.ReadCloser, error) {
    tr := http.DefaultTransport.(*http.Transport).Clone()
    tr.TLSClientConfig = &tls.Config{InsecureSkipVerify: opt.insecure}
    if opt.proxy != "" {
        proxy, err := url.Parse(opt.proxy)
        if err != nil { return nil, err }
        tr.Proxy = func(req *http.Request) (*url.URL, error) {
            if bypassProxy(req.URL, opt.noProxy) { return nil, nil }
            return proxy, nil
        }
    }
    client := &http.Client{Transport: tr}
    req, err := http.NewRequest("GET", address, nil)
    if err != nil { return nil, err }
    req.Header.Set("Accept", "application/json")
    req.Header.Set("User-Agent", "gron/dev")
    resp, err := client.Do(req)
    if err != nil { return nil, err }
    return resp.Body, nil
}

func bypassProxy(u *url.URL, list string) bool {
    host := strings.ToLower(u.Hostname())
    for _, item := range strings.Split(list, ",") {
        item = strings.ToLower(strings.TrimSpace(item))
        if item == "*" { return true }
        if item == "" { continue }
        if item == strings.ToLower(u.Host) || host == item || strings.HasSuffix(host, "."+strings.TrimPrefix(item,".")) { return true }
    }
    return false
}

// Read arbitrarily long logical lines, preserving an unterminated last line.
// Unlike Scanner, this is not limited to 64 KiB.
func eachLine(r io.Reader, visit func(string) error) error {
    br := bufio.NewReader(r)
    for {
        line, err := br.ReadString('\n')
        if len(line) != 0 {
            line = strings.TrimSuffix(line, "\n")
            line = strings.TrimSuffix(line, "\r")
            if e := visit(line); e != nil { return e }
        }
        if err == io.EOF { return nil }
        if err != nil { return err }
    }
}
EOF
cat > forward.go <<'EOF'
package main

import (
    "encoding/json"
    "fmt"
    "io"
    "sort"
    "strconv"
    "strings"
    "unicode"
)

// Identifiers may use Unicode letters and combining marks, but a reserved
// word is always represented by a quoted subscript.
var reserved = func() map[string]bool {
    out := make(map[string]bool)
    for _, k := range strings.Fields("break case catch class const continue debugger default delete do else export extends false finally for function if import in instanceof new null return super switch this throw true try typeof var void while with yield") {
        out[k] = true
    }
    return out
}()

func idStart(r rune) bool {
    return r == '$' || r == '_' || unicode.IsLetter(r) || unicode.Is(unicode.Nl, r)
}
func idPart(r rune) bool {
    return idStart(r) || unicode.Is(unicode.Nd,r) || unicode.Is(unicode.Mn,r) || unicode.Is(unicode.Mc,r) || unicode.Is(unicode.Pc,r)
}
func identifier(s string) bool {
    if s == "" || reserved[s] { return false }
    for i, r := range s {
        if i == 0 { if !idStart(r) { return false } } else if !idPart(r) { return false }
    }
    return true
}

// The assignment notation uses JavaScript-safe escapes. C1 controls and
// line/paragraph separators are escaped too, with uppercase hexadecimal.
func quoteJS(s string) string {
    var b strings.Builder
    b.WriteByte('"')
    for _, r := range s {
        switch r {
        case '"': b.WriteString(`\"`)
        case '\\': b.WriteString(`\\`)
        case '\b': b.WriteString(`\b`)
        case '\f': b.WriteString(`\f`)
        case '\n': b.WriteString(`\n`)
        case '\r': b.WriteString(`\r`)
        case '\t': b.WriteString(`\t`)
        default:
            if r < 0x20 || (r >= 0x7f && r <= 0x9f) || r == 0x2028 || r == 0x2029 {
                fmt.Fprintf(&b, `\u%04X`, r)
            } else { b.WriteRune(r) }
        }
    }
    b.WriteByte('"')
    return b.String()
}

func paint(s, style string, enabled bool) string {
    if !enabled { return s }
    close := "0"
    if style == "34;1" { close = "0;22" }
    if style == "1" { close = "22" }
    return "\x1b["+style+"m"+s+"\x1b["+close+"m"
}

type pathPart struct {
    name string
    index int
    isIndex bool
}

type assignment struct {
    path []pathPart
    value interface{}
}

func displayValue(v interface{}, color bool) string {
    switch x := v.(type) {
    case nil: return paint("null", "36", color)
    case bool: return paint(strconv.FormatBool(x), "36", color)
    case string: return paint(quoteJS(x), "33", color)
    case json.Number: return paint(string(x), "31", color)
    case float64:
        b, _ := json.Marshal(x)
        return paint(string(b), "31", color)
    case []interface{}: return paint("[]", "35", color)
    case map[string]interface{}: return paint("{}", "35", color)
    }
    return "null"
}

func renderAssignment(a assignment, jsonMode, color bool) string {
    var b strings.Builder
    if jsonMode {
        b.WriteString(paint("[", "35", color))
        b.WriteString(paint("[", "35", color))
        for i, p := range a.path {
            if i != 0 { b.WriteByte(',') }
            if p.isIndex { b.WriteString(paint(strconv.Itoa(p.index), "31", color)) } else { b.WriteString(paint(quoteJS(p.name), "33", color)) }
        }
        b.WriteString(paint("]", "35", color))
        b.WriteByte(',')
        b.WriteString(displayValue(a.value, color))
        b.WriteString(paint("]", "35", color))
    } else {
        b.WriteString(paint("json", "34;1", color))
        for _, p := range a.path {
            if p.isIndex {
                b.WriteString(paint("[", "35", color))
                b.WriteString(paint(strconv.Itoa(p.index), "31", color))
                b.WriteString(paint("]", "35", color))
            } else if identifier(p.name) {
                b.WriteByte('.')
                b.WriteString(paint(p.name, "34;1", color))
            } else {
                b.WriteString(paint("[", "35", color))
                b.WriteString(paint(quoteJS(p.name), "33", color))
                b.WriteString(paint("]", "35", color))
            }
        }
        b.WriteString(" = ")
        b.WriteString(displayValue(a.value, color))
        b.WriteByte(';')
    }
    b.WriteByte('\n')
    return b.String()
}

func keyOrder(k string) string {
    if identifier(k) { return "."+k }
    return "["+quoteJS(k)+"]"
}

func emitTree(w io.Writer, v interface{}, path []pathPart, opt options) {
    fmt.Fprint(w, renderAssignment(assignment{path, v}, opt.json, opt.ansi))
    switch x := v.(type) {
    case map[string]interface{}:
        keys := make([]string,0,len(x))
        for k := range x { keys = append(keys,k) }
        if !opt.noSort { sort.Slice(keys,func(i,j int) bool { return keyOrder(keys[i]) < keyOrder(keys[j]) }) }
        for _, k := range keys {
            emitTree(w,x[k],append(path,pathPart{name:k}),opt)
        }
    case []interface{}:
        for i, value := range x {
            emitTree(w,value,append(path,pathPart{index:i,isIndex:true}),opt)
