    tokStringValue
    tokObjectValue
    tokArrayValue
    tokLiteralValue
    tokSemi
    tokInvalid
)

type token struct {
    kind tokenKind
    text string
}

type statement []token

func (s statement) String() string {
    var b strings.Builder
