}

// Assignment input is intentionally line-oriented: only the first assignment
// on a line is significant. The small lexer preserves token spellings, which
// is important for numeric values and for the raw --values operation.
func lexAssignment(s string) statement {
    out := statement{}
    i := 0
    add := func(k tokenKind, text string) { out = append(out, token{k,text}) }
    invalid := func() statement { add(tokInvalid, ""); return out }
    spaces := func() { for i < len(s) && s[i] == ' ' { i++ } }
    readName := func() (string, bool) {
        start := i
        for i < len(s) {
            r, n := utf8.DecodeRuneInString(s[i:])
            if !idPart(r) { break }
            i += n
        }
        if i < len(s) && s[i] == '-' {
            i = len(s)
            return s[start:i], true
        }
        return s[start:i], false
    }
    for i < len(s) {
        switch s[i] {
        case ' ':
            spaces()
            if i >= len(s) || s[i] != '=' { return out }
        case '=':
            add(tokEqual, "=")
            i++
            spaces()
            start := i
            k := tokRawValue
            if i < len(s) {
                switch s[i] {
                case '"':
                    k = tokStringValue
                    i = quotedEnd(s,i)
                case '{','[','t','f','n':
                    var literal string
                    switch s[i] {
                    case '{': literal = "{}"; k = tokObjectValue
                    case '[': literal = "[]"; k = tokArrayValue
                    case 't': literal = "true"; k = tokLiteralValue
                    case 'f': literal = "false"; k = tokLiteralValue
                    case 'n': literal = "null"; k = tokLiteralValue
                    }
                    for n := 0; n < len(literal) && i < len(s) && s[i] == literal[n]; n++ { i++ }
                default:
                    for i < len(s) && s[i] != ';' { i++ }
                }
            }
            add(k,s[start:i])
            spaces()
            if i < len(s) && s[i] == ';' { add(tokSemi,";") }
            return out
        case '.':
            add(tokDot,".")
            i++
            if i >= len(s) { return invalid() }
            r,_ := utf8.DecodeRuneInString(s[i:])
            if !idStart(r) { return invalid() }
            name, rest := readName()
            add(tokIdentifier,name)
            if rest { return out }
        case '[':
            add(tokOpen,"[")
            i++
            if i >= len(s) { return invalid() }
            if s[i] == '"' {
                start := i
                i = quotedEnd(s,i)
                add(tokQuotedKey,s[start:i])
            } else if s[i] >= '0' && s[i] <= '9' {
                start := i
                for i < len(s) && s[i] >= '0' && s[i] <= '9' { i++ }
                add(tokIntegerKey,s[start:i])
            } else { return invalid() }
            if i >= len(s) || s[i] != ']' { return invalid() }
            add(tokClose,"]")
            i++
        default:
            r,_ := utf8.DecodeRuneInString(s[i:])
            if !idStart(r) { return invalid() }
            first := len(out) == 0
            name, rest := readName()
            if first && !rest {
                j := i
                for j < len(s) && s[j] == ' ' { j++ }
                if j == len(s) || (i < len(s) && s[i] == ' ' && s[j] != '=') { return out }
            }
            add(tokIdentifier,name)
            if rest { return out }
        }
    }
    return out
}

func quotedEnd(s string, start int) int {
    i := start+1
    for i < len(s) {
        c := s[i]
        i++
        if c == '\\' {
            if i < len(s) { _,n := utf8.DecodeRuneInString(s[i:]); i+=n }
        } else if c == '"' { return i }
    }
    return i
}

func (s statement) toNode() (interface{}, error) {
    for _, t := range s {
        if t.kind == tokInvalid { return nil, errors.New("invalid statement") }
    }
    if len(s) == 0 { return nil, errors.New("invalid statement") }
    if s[len(s)-1].kind != tokSemi { return nil, errors.New("statement has no value") }
    eq := -1
    for i, t := range s { if t.kind == tokEqual { eq = i; break } }
    if eq == -1 || eq+1 >= len(s)-1 { return nil, errors.New("statement has no value") }
    valueText := s[eq+1].text
    // Decode a single JSON value so that JSON number spellings are retained.
    value, err := readJSON(strings.NewReader(valueText))
    if err != nil { return nil, fmt.Errorf("invalid value `%s`",valueText) }
    path := []pathPart{}
    seenPath := false
    for _, t := range s[:eq] {
        switch t.kind {
        case tokIdentifier:
            if !seenPath && t.text == "json" { seenPath = true; continue }
            path = append(path,pathPart{name:t.text})
            seenPath = true
        case tokQuotedKey:
            var key string
            if err := json.Unmarshal([]byte(t.text),&key); err != nil { return nil, fmt.Errorf("invalid quoted key `%s`",t.text) }
            path = append(path,pathPart{name:key})
            seenPath = true
        case tokIntegerKey:
            n,err := strconv.Atoi(t.text)
            if err != nil || n < 0 { return nil, fmt.Errorf("invalid integer key `%s`",t.text) }
            path = append(path,pathPart{index:n,isIndex:true})
            seenPath = true
        }
    }
    return nestValue(path,value)
}

func nestValue(path []pathPart, value interface{}) (interface{},error) {
    for i := len(path)-1; i >= 0; i-- {
        p := path[i]
        if p.isIndex {
            // Avoid exhausting the host for an unrepresentable subscript.
            if p.index < 0 || p.index > 16000000 { return nil, fmt.Errorf("invalid integer key `%d`",p.index) }
            a := make([]interface{},p.index+1)
            a[p.index] = value
            value = a
        } else { value = map[string]interface{}{p.name:value} }
    }
    return value,nil
}

func mergeNodes(old, next interface{}) (interface{}, error) {
    switch a := old.(type) {
    case map[string]interface{}:
        b,ok := next.(map[string]interface{})
        if !ok { return nil, errors.New("cannot merge object with non-object") }
        for key, value := range b {
            prev,exists := a[key]
            if !exists { a[key] = value; continue }
            merged,err := mergeNodes(prev,value)
            if err != nil { return nil,err }
            a[key] = merged
        }
        return a,nil
    case []interface{}:
        b,ok := next.([]interface{})
        if !ok { return nil,errors.New("cannot merge array with non-array") }
        if len(b) > len(a) { a = append(a,make([]interface{},len(b)-len(a))...) }
        for i,value := range b {
            // Both explicit nulls and holes are non-destructive within arrays.
            if value == nil { continue }
            merged,err := mergeNodes(a[i],value)
            if err != nil { return nil,err }
            a[i] = merged
        }
        return a,nil
    default: return next,nil
    }
}

func jsonStatement(line string) (statement,error) {
    var data []interface{}
    if err := json.Unmarshal([]byte(line),&data); err != nil { return nil,err }
    layoutError := errors.New("invalid JSON layout")
    if len(data) != 2 { return nil,layoutError }
    parts,ok := data[0].([]interface{})
    if !ok { return nil,layoutError }
    switch v := data[1].(type) {
    case []interface{}: if len(v) != 0 { return nil,layoutError }
    case map[string]interface{}: if len(v) != 0 { return nil,layoutError }
    }
    out := statement{{tokIdentifier,"json"}}
    for _, part := range parts {
        switch v := part.(type) {
        case string:
