        case float64:
            text,_ := json.Marshal(v)
            out = append(out,token{tokOpen,"["},token{tokIntegerKey,string(text)},token{tokClose,"]"})
        default: return nil,layoutError
        }
    }
    out = append(out,token{tokEqual,"="},token{tokRawValue,displayValue(data[1],false)},token{tokSemi,";"})
    return out,nil
}

