func TestColorAndEnvironment(t *testing.T) {
    got := invoke(t,[]string{"-c","-m"},"1",nil)
    want := result{0,"\x1b[34;1mjson\x1b[0;22m = \x1b[31m1\x1b[0m;\n",""}
    if got != want { t.Fatalf("got %#v, want %#v",got,want) }
    got = invoke(t,[]string{"-u","-c"},`json="x";`,nil)
    want = result{0,"\x1b[32m\"\x1b[0m\x1b[33mx\x1b[0m\x1b[32m\"\x1b[0m\n",""}
    if got != want { t.Fatalf("got %#v, want %#v",got,want) }
    got = invoke(t,[]string{"-u","-c"},"json.a=1;",map[string]string{"NO_COLOR":"1"})
    want = result{0,"{\"a\":1}\n",""}
    if got != want { t.Fatalf("got %#v, want %#v",got,want) }
}

func TestFileInput(t *testing.T) {
    name := filepath.Join(t.TempDir(),"input.json")
    if err := os.WriteFile(name,[]byte(`{"a":true}`),0600); err != nil { t.Fatal(err) }
    got := invoke(t,[]string{name,"ignored"},"null",nil)
    want := result{0,"json = {};\njson.a = true;\n",""}
    if got != want { t.Fatalf("got %#v, want %#v",got,want) }
    os.Remove(name)
    got = invoke(t,[]string{name},"",nil)
    if got.code != 1 || got.err != "open "+name+": no such file or directory\n" { t.Fatalf("got %#v",got) }
}

func TestHTTPInput(t *testing.T) {
    direct := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){
        if r.Header.Get("Accept") != "application/json" || r.UserAgent() != "gron/dev" { t.Error("incorrect request headers") }
        w.WriteHeader(http.StatusNotFound)
        io.WriteString(w,`{"server":"direct"}`)
    }))
    defer direct.Close()
    proxy := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){
        if !r.URL.IsAbs() { t.Error("proxy request is not absolute") }
        io.WriteString(w,`{"server":"proxy"}`)
    }))
    defer proxy.Close()
    u,_ := url.Parse(direct.URL)
    tests := []struct { opt options; server string } {
        {options{},"direct"},
        {options{proxy:proxy.URL},"proxy"},
        {options{proxy:proxy.URL,noProxy:u.Host},"direct"},
        {options{proxy:proxy.URL,noProxy:u.Hostname()},"proxy"},
        {options{proxy:proxy.URL,noProxy:"*"},"proxy"},
        {options{proxy:"%"},"direct"},
    }
    for _,test := range tests {
        r,err := fetch(direct.URL,test.opt)
        if err != nil { t.Fatal(err) }
        data,err := io.ReadAll(r); r.Close()
        if err != nil || !strings.Contains(string(data),test.server) { t.Fatalf("response %q, error %v",data,err) }
    }
}
